<script setup>import{onMounted,onUnmounted,ref,watch}from'vue';import{twinApi}from'../api';import{useRealtimeStore}from'../store';import{WarehouseScene}from'../three/WarehouseScene';const el=ref(),store=useRealtimeStore();let scene;onMounted(async()=>{scene=new WarehouseScene(el.value);scene.syncSlots(await twinApi.slots())});watch(()=>store.lastMessage,m=>{if(!m||!scene)return;if(m.type==='slot_update')scene.updateSlot(m.slotId,m.status,m.data?.cargoType);if(m.type==='detection')scene.updateAgents(m.data)});onUnmounted(()=>scene?.dispose())</script>
<template><div class="toolbar"><el-tag type="success">绿色：已占用</el-tag><el-tag type="info">灰色：空闲</el-tag><el-tag type="danger">红色：异常</el-tag><span style="color:#77827c;font-size:12px">WebSocket 状态变化会实时增删货物模型</span></div><div ref="el" class="twin-canvas"></div></template>
